function normalizePollInteger(e,t){const n=typeof e===`number`&&Number.isFinite(e)?Math.floor(e):void 0;if(n!==void 0&&n<1)throw new Error(`${t} must be at least 1`);return n}function resolvePollMaxSelections(e,t){return t?Math.max(2,e):1}function normalizePollInput(e,t={}){const n=e.question.trim();if(!n)throw new Error(`Poll question is required`);const r=(e.options??[]).map(e=>e.trim()).filter(Boolean);if(r.length<2)throw new Error(`Poll requires at least 2 options`);if(t.maxOptions!==void 0&&r.length>t.maxOptions)throw new Error(`Poll supports at most ${t.maxOptions} options`);const i=normalizePollInteger(e.maxSelections,`maxSelections`)??1;if(i>r.length)throw new Error(`maxSelections cannot exceed option count`);const a=normalizePollInteger(e.durationSeconds,`durationSeconds`);const o=normalizePollInteger(e.durationHours,`durationHours`);if(a!==void 0&&o!==void 0)throw new Error(`durationSeconds and durationHours are mutually exclusive`);return{question:n,options:r,maxSelections:i,durationSeconds:a,durationHours:o}}function normalizePollDurationHours(e,t){const n=typeof e===`number`&&Number.isFinite(e)?Math.floor(e):t.defaultHours;return Math.min(Math.max(n,1),t.maxHours)}export{normalizePollInput as n,resolvePollMaxSelections as r,normalizePollDurationHours as t};